using System;
using System.Linq;

public class FunctionalTransform
{
    public static int SumOfDoubledOdds(int[] numbers)
    {
        if (numbers == null) return 0;
        return numbers
            .Where(n => n % 2 != 0)
            .Select(n => n * 2)
            .Sum();
    }

    public static void Main()
    {
        int[] data = { 1, 2, 3, 4, 5 };
        Console.WriteLine($"Total: {SumOfDoubledOdds(data)}");
    }
}
